-- Challah covers from the supplier (Art Judaica), 128 products (covers,
-- challah bags, sets with a knife cover), in Hebrew, French and English, as
-- single items for the custom gift box, under Shabbat > challah covers.
-- Price: the supplier's price × 2.5, rounded to the shekel.
-- They come in HIDDEN: in the admin area switch on the ones you want.
-- Run it ONCE: running it again would bring back products you deleted.

insert into public.products
  (id, category, categories, name_he, name_fr, name_en, subtitle_he, subtitle_fr, subtitle_en,
   description_he, description_fr, description_en, price, images, active, in_stock, kind, sort)
values
  ('art-UK60181', 'shabbat', array['shabbat','shabbat-challah-covers','judaica']::text[],
   'כיסוי חלה פיו לבן האש שלי שבת קודש רקמה כסף 54X45 ס"מ', 'Couvre-challah façon cuir blanc « Ma flamme », Chabbat Kodech, broderie argent, 54×45 cm', 'White leather-look challah cover "My Flame", Shabbat Kodesh, silver embroidery, 54×45 cm',
   'דמוי עור · 54 × 44 ס״מ', 'façon cuir · 54 × 44 cm', 'leather look · 54 × 44 cm',
   'כיסוי חלה מהודר בגוון לבן אלגנטי מדמוי עור, עם רקמת כסף מרהיבה במרכזו המעצבת להבת אש נאה, ומסביבה הכיתוב "שבת קודש - מוקד עד ביאת משיח". עיצוב מכובד ומרשים המוסיף חן וזוהר לשולחן השבת, ומתאים כמתנה יוקרתית או לשימוש עצמי בבית.',
   'Couvre-challah élégant façon cuir blanc, avec au centre une superbe broderie argentée en forme de flamme, entourée de l''inscription « Chabbat Kodech ». Un design digne et remarquable qui ajoute charme et éclat à la table de Chabbat, idéal comme cadeau luxueux ou pour la maison.',
   'An elegant challah cover in white leather look, with a stunning silver embroidery of a flame at its centre, surrounded by the inscription "Shabbat Kodesh". A dignified, impressive design that adds charm and glow to the Shabbat table, suitable as a luxurious gift or for your own home.',
   175, array['/products/art/uk60181-1.webp','/products/art/uk60181-2.webp','/products/art/uk60181-3.webp']::text[], false, true, 'item', 1600),  -- 69.99 × 2.5
  ('art-UK67710', 'shabbat', array['shabbat','shabbat-challah-covers','judaica']::text[],
   'כיסוי חלה מהודר דמוי עור לבן האש שלי 45X55 ס"מ', 'Couvre-challah élégant façon cuir blanc « Ma flamme », 45×55 cm', 'Elegant white leather-look challah cover "My Flame", 45×55 cm',
   'דמוי עור · 55 × 45 ס״מ', 'façon cuir · 55 × 45 cm', 'leather look · 55 × 45 cm',
   'כיסוי חלה מהודר דמוי עור בגוון לבן שמנת, מעוצב בעדינות עם אפליקציית להבת אש מוכספת בולטת במרכז, ומסביבה הכיתוב "שבת קודש - חוקד עד ביאת משיח" ברקמה מכסיפה. עיצוב אלגנטי ומרשים המוסיף חגיגיות לשולחן השבת, מתנה מושלמת לכל בית יהודי.',
   'Couvre-challah élégant façon cuir blanc crème, orné au centre d''une flamme argentée en relief, entourée d''une inscription brodée en argent. Un design élégant et remarquable qui ajoute de la festivité à la table de Chabbat : un cadeau parfait pour chaque foyer juif.',
   'An elegant challah cover in cream-white leather look, delicately designed with a raised silver flame appliqué at the centre, surrounded by a silver-embroidered inscription. An elegant, impressive design that adds festivity to the Shabbat table, a perfect gift for any Jewish home.',
